118	// tokenizeInput splits input on whitespace but respects quoted values after filter prefixes.
119	// Example: `author:"alice smith" fix bug` → ["author:\"alice smith\"", "fix", "bug"]
120	func tokenizeInput(s string) []string {
121		var tokens []string
122		i := 0
123		s = strings.TrimSpace(s)
124		for i < len(s) {
125			// Skip whitespace
126			for i < len(s) && s[i] == ' ' {
127				i++
128			}
129			if i >= len(s) {
130				break
131			}
132	
133			start := i
134	
135			// Look ahead: is this a prefix:"quoted" token?
136			if colonIdx := strings.Index(s[i:], ":\""); colonIdx >= 0 && !strings.Contains(s[i:i+colonIdx], " ") {
137				// Found prefix:" — scan to closing quote
138				quoteStart := i + colonIdx + 2
139				endQuote := strings.IndexByte(s[quoteStart:], '"')
140				if endQuote >= 0 {
141					i = quoteStart + endQuote + 1
142					tokens = append(tokens, s[start:i])
143					continue
144				}
145			}
146	
147			// Regular token: advance to next space
148			for i < len(s) && s[i] != ' ' {
