// Shared types for search — used by both the API route (routes/search.ts)
// and the standalone search worker (search-worker/).

export type SearchMatchType = "keyword" | "semantic" | "both"

export interface SearchMeta {
  matchType: SearchMatchType
  score: number
  snippet?: string
}

export interface RepoResult {
  id: string
  githubRepoId: number
  org: string
  name: string
  fullName: string
  description: string | null
  checkpointCount: number
}

export interface CheckpointResult {
  id: string
  prompt: string
  commitMessage: string | null
  commitSha: string | null
  branch: string
  org: string
  repo: string
  author: string
  authorUsername: string | null
  createdAt: string
  filesTouched: string[]
}

export type SearchResult =
  | { type: "repo"; data: RepoResult; searchMeta: SearchMeta }
  | { type: "checkpoint"; data: CheckpointResult; searchMeta: SearchMeta }

export interface SearchTiming {
  total_ms: number
  keyword_ms: number | null
  embedding_ms: number | null
  vector_ms: number | null
  rerank_ms: number | null
}

export interface SearchResponse {
  results: SearchResult[]
  total: number
  page: number
  timing: SearchTiming
  reranked?: boolean
}

export interface SearchParams {
  q: string
  types?: ("repos" | "checkpoints")[]
  repo?: string
  branch?: string
  author?: string
  date?: "week" | "month"
  page: number
  limit: number
  perType: { repos: number; checkpoints: number }
}

// Search-specific DB queries used by the search worker.
// These are separate from the namespace factory pattern used by the API routes.

import { Kysely, sql } from "kysely"

import type { DB } from "../../../db/types"

// ─── User lookup ──────────────────────────────────────────────────────────────

export async function getUserByGithubId(
  db: Kysely<DB>,
  githubId: number,
): Promise<{ id: string; github_login: string | null } | null> {
  const row = await db
    .selectFrom("users")
    .select(["id", "github_login"])
    .where("github_id", "=", githubId)
    .executeTakeFirst()
  return row ?? null
}

// ─── Checkpoint keyword search ────────────────────────────────────────────────

export async function searchCheckpointsKeyword(
  db: Kysely<DB>,
  opts: {
    query: string
    userId: string
    repo?: string
    branch?: string
    author?: string
    date?: "week" | "month"
    limit: number
  },
): Promise<any[]> {
  const dateThresholds = {
    week: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000),
    month: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000),
  }

  const escapedQuery = opts.query.replace(/[\\%_]/g, "\\$&")

  let q = db
    .selectFrom("repo_checkpoints as cp")
    .innerJoin("repo_checkpoint_commits as cc", (join) =>
      join
        .onRef("cc.repo_id", "=", "cp.repo_id")
        .onRef("cc.checkpoint_id", "=", "cp.checkpoint_id"),
    )
    .innerJoin("repo_commits as rc", (join) =>
      join.onRef("rc.repo_id", "=", "cc.repo_id").onRef("rc.commit_sha", "=", "cc.commit_sha"),
    )
    .innerJoin("repos", "repos.id", "cp.repo_id")
    .innerJoin("user_repos", "user_repos.repo_id", "repos.id")
    .where("user_repos.user_id", "=", opts.userId)
    .where((eb) =>
      eb.or([
        eb("cp.prompt", "like", `%${escapedQuery}%`),
        eb("rc.commit_message", "like", `%${escapedQuery}%`),
      ]),
    )
    .select([
      "cp.checkpoint_id",
      "cp.prompt",
      "cp.files_touched",
      "cp.created_at",
      "rc.commit_message",
      "cc.commit_sha",
      "cc.branch",
      "rc.commit_author as author",
      "rc.commit_author_username as author_username",
      "repos.full_name as repo_full_name",
    ])

  if (opts.repo) {
    q = q.where("repos.full_name", "=", opts.repo)
  }
  if (opts.branch) {
    q = q.where("cc.branch", "=", opts.branch)
  }
  if (opts.author) {
    q = q.where("rc.commit_author_username", "=", opts.author)
  }
  if (opts.date) {
    q = q.where("cp.created_at", ">=", dateThresholds[opts.date])
  }

  // Over-fetch to absorb duplicate rows from commit join, dedup at app layer.
  // Sort: rows where commit_message matches come first.
  const rows = await q
    .orderBy(sql`(rc.commit_message LIKE ${`%${escapedQuery}%`})`, "desc")
    .orderBy("cp.created_at", "desc")
    .limit(opts.limit * 4)
    .execute()

  const seen = new Set<string>()
  const deduped: typeof rows = []
  for (const row of rows) {
    if (!seen.has(row.checkpoint_id)) {
      seen.add(row.checkpoint_id)
      deduped.push(row)
      if (deduped.length >= opts.limit) break
    }
  }

  return deduped.map((row) => {
    const parts = (row.repo_full_name ?? "").split("/")
    return {
      ...row,
      org: parts[0] ?? "",
      repo: parts[1] ?? "",
    }
  })
}

// ─── Checkpoint hydration by IDs ──────────────────────────────────────────────

export async function getCheckpointsByIdsGlobal(
  db: Kysely<DB>,
  checkpointIds: string[],
  userId: string,
): Promise<any[]> {
  if (checkpointIds.length === 0) return []

  const rows = await db
    .selectFrom("repo_checkpoints as cp")
    .innerJoin("repo_checkpoint_commits as cc", (join) =>
      join
        .onRef("cc.repo_id", "=", "cp.repo_id")
        .onRef("cc.checkpoint_id", "=", "cp.checkpoint_id"),
    )
    .innerJoin("repo_commits as rc", (join) =>
      join.onRef("rc.repo_id", "=", "cc.repo_id").onRef("rc.commit_sha", "=", "cc.commit_sha"),
    )
    .innerJoin("repos", "repos.id", "cp.repo_id")
    .innerJoin("user_repos", "user_repos.repo_id", "cp.repo_id")
    .where("user_repos.user_id", "=", userId)
    .where("cp.checkpoint_id", "in", checkpointIds)
    .select([
      "cp.checkpoint_id",
      "cp.prompt",
      "cp.files_touched",
      "cp.created_at",
      "rc.commit_message",
      "cc.commit_sha",
      "cc.branch",
      "rc.commit_author as author",
      "rc.commit_author_username as author_username",
      "repos.full_name as repo_full_name",
    ])
    // Prefer main/master branches for dedup
    .orderBy(sql`CASE cc.branch WHEN 'main' THEN 0 WHEN 'master' THEN 1 ELSE 2 END`)
    .orderBy("cc.branch", "asc")
    .execute()

  // Deduplicate: checkpoint on multiple branches produces multiple rows
  const seen = new Set<string>()
  const deduped: typeof rows = []
  for (const row of rows) {
    if (!seen.has(row.checkpoint_id)) {
      seen.add(row.checkpoint_id)
      deduped.push(row)
    }
  }

  return deduped.map((row) => {
    const parts = (row.repo_full_name ?? "").split("/")
    return {
      ...row,
      org: parts[0] ?? "",
      repo: parts[1] ?? "",
    }
  })
}

