func TestSearch_MultiRepoParams(t *testing.T) {
	t.Parallel()

	var capturedReq *http.Request
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		capturedReq = r
		resp := Response{Results: []Result{}, Total: 0, Page: 1}
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(resp) //nolint:errcheck // test helper response
	}))
	defer srv.Close()

	_, err := Search(context.Background(), Config{
		ServiceURL:  srv.URL,
		GitHubToken: "tok",
		Owner:       "default-owner",
		Repo:        "default-repo",
		Query:       "q",
		Repos:       []string{"owner-one/repo-a", "owner-two/repo-b"},
	})
	if err != nil {
		t.Fatal(err)
	}

	if got := capturedReq.URL.Query()["repo"]; len(got) != 2 {
		t.Fatalf("repo params = %v, want 2 repeated params", got)
	} else if got[0] != "owner-one/repo-a" || got[1] != "owner-two/repo-b" {
		t.Errorf("repo params = %v, want %v", got, []string{"owner-one/repo-a", "owner-two/repo-b"})
	}
}

